from datetime import timedelta

import database
import support


class DataStatusTests(support.DatabaseCase):
    """Count each series once and label synthetic users even with exclusively real events."""

    def test_empty_and_real_only_data(self):
        """A new database and real-only imports must not be labelled as placeholder data."""
        expected = {'placeholder_series': 0, 'synthetic_users': 0}
        self.assertEqual(database.get_demo_counts(self.connection), expected)
        self.save()
        database.create_user(self.connection, 'Alex', now=support.NOW)
        self.assertEqual(database.get_demo_counts(self.connection), expected)

    def test_mixed_sources_count_series_not_occurrences(self):
        """Recurring placeholder occurrences count once alongside a real series."""
        rows = [support.record(external_id='demo'), support.record(
            external_id='demo', start=support.NOW + timedelta(days=2),
            end=support.NOW + timedelta(days=2, hours=2))]
        self.save(rows, is_placeholder=True)
        self.save([support.record(external_id='real')])
        self.assertEqual(database.get_demo_counts(self.connection)['placeholder_series'], 1)

    def test_synthetic_users_are_independent_of_source_origin(self):
        """Real event sources still display the demo badge while synthetic users remain."""
        self.save()
        # Course: A07 – use the same transactional user insert as the demo generator.
        database.create_user(self.connection, 'Lena', is_synthetic=True, now=support.NOW)
        self.assertEqual(database.get_demo_counts(self.connection),
                         {'placeholder_series': 0, 'synthetic_users': 1})
